func detectDocPaths() []string {
	var paths []string
	if info, err := os.Stat("docs"); err == nil && info.IsDir() {
		paths = append(paths, "docs/")
	}
	if _, err := os.Stat("README.md"); err == nil {
		paths = append(paths, "README.md")
	}
	return paths
}

