func joinPaths(paths []string) string {
	s := ""
	for i, p := range paths {
		if i > 0 {
			s += ", "
		}
		s += p
	}
	return s
}

type ProjectInfo struct {
	// HasGit is true if a .git directory exists.
	HasGit bool
	// GitRemote is the origin remote URL, if available.
	GitRemote string
	// Language detected from manifest files ("go", "typescript", etc.).
	Language string
	// HasDocs is true if a docs/ directory or README.md exists.
	HasDocs bool
	// DocPaths lists detected documentation paths.
	DocPaths []string
	// ConfigFiles lists detected config files (go.mod, package.json, Dockerfile, etc.).
	ConfigFiles []string
	// HasImages is true if one or more common image directories are found.
	HasImages bool
	// ImagePaths lists detected image directories.
	ImagePaths []string
	// DirName is the base name of the working directory.
	DirName string
	// Namespace is the best-guess org name (from git remote or dir name).
	Namespace string
}

func sourceLocation(s config.SourceEntry) string {
	switch s.Type {
	case "ast":
		return s.Path
	case "git", "repo":
		if s.URL != "" {
			return s.URL
		}
		return s.Path
	case "docs", "config", "image", "video", "audio":
		return strings.Join(s.Paths, ", ")
	case "url":
		if len(s.URLs) > 0 {
			return s.URLs[0]
		}
	}
	return ""
}

func parseRepoFlags(args []string) (*config.SourceEntry, error) {
	fs := flag.NewFlagSet("add repo", flag.ContinueOnError)
	url := fs.String("url", "", "remote repository URL to clone and analyze")
	branch := fs.String("branch", "", "branch (default: remote default)")
	language := fs.String("language", "", "primary language (go, java, python, typescript, or leave blank to auto-detect)")
	watch := fs.Bool("watch", true, "watch for changes")
	if err := fs.Parse(args); err != nil {
		return nil, err
	}
	if *url == "" {
		return nil, fmt.Errorf("repo source requires --url")
	}
	return &config.SourceEntry{
		Type:     "repo",
		URL:      *url,
		Branch:   *branch,
		Language: *language,
		Watch:    *watch,
	}, nil
}

func printDetectionSummary(term *Term, info *ProjectInfo) {
	var found []string
	if info.HasGit {
		found = append(found, "git repo")
	}
	if info.Language != "" {
		found = append(found, info.Language+" project")
	}
	if info.HasDocs {
		found = append(found, "docs")
	}
	if len(info.ConfigFiles) > 0 {
		found = append(found, fmt.Sprintf("%d config file(s)", len(info.ConfigFiles)))
	}
	if info.HasImages {
		found = append(found, fmt.Sprintf("%d image dir(s)", len(info.ImagePaths)))
	}

	if len(found) > 0 {
		term.Info(fmt.Sprintf("Detected: %s", strings.Join(found, ", ")))
	} else {
		term.Info("No project files detected — you'll configure sources manually.")
	}
	fmt.Fprintln(term.out)
}

func InitQuick(term *Term, configPath string, overrides ...*ProjectInfo) error {
	if configPath == "" {
		configPath = defaultConfigPath
	}

	// Warn if config already exists.
	if _, err := os.Stat(configPath); err == nil {
		term.Println(fmt.Sprintf("  %s already exists.", configPath))
		if !term.Confirm("Overwrite it?", false) {
			term.Info("Aborted.")
			return nil
		}
	}

	var info *ProjectInfo
	if len(overrides) > 0 && overrides[0] != nil {
		info = overrides[0]
	} else {
		dir, _ := os.Getwd()
		info = DetectProject(dir)
	}

	if info.Namespace == "" {
		term.Info("Could not auto-detect project details. Falling back to interactive mode.")
		return Init(term, configPath)
	}

	term.Header("semsource quick setup")
	printDetectionSummary(term, info)

	// Build sources from detected context.
	sources := buildDetectedSources(info)
	if len(sources) == 0 {
		term.Info("No sources detected. Falling back to interactive mode.")
		return Init(term, configPath)
	}

	cfg := buildConfig(info.Namespace, sources)

	return writeAndSummarize(term, configPath, cfg)
}

