func ffmpegAvailable() bool {
	_, err := exec.LookPath("ffmpeg")
	return err == nil
}

func orgFromRemote(remote string) string {
	// SSH format: git@host:org/repo.git
	if strings.Contains(remote, ":") && strings.Contains(remote, "@") {
		parts := strings.SplitN(remote, ":", 2)
		if len(parts) == 2 {
			path := strings.TrimSuffix(parts[1], ".git")
			segs := strings.Split(path, "/")
			if len(segs) >= 2 {
				return sanitizeName(segs[0])
			}
		}
	}

	// HTTPS format: https://host/org/repo.git
	remote = strings.TrimSuffix(remote, ".git")
	// Remove scheme.
	if idx := strings.Index(remote, "://"); idx >= 0 {
		remote = remote[idx+3:]
	}
	segs := strings.Split(remote, "/")
	// host/org/repo -> segs[1] is org
	if len(segs) >= 3 {
		return sanitizeName(segs[1])
	}

	return ""
}

func (t *Term) Info(msg string) {
	fmt.Fprintln(t.out, msg)
}

func Sources(term *Term, configPath string) error {
	if configPath == "" {
		configPath = defaultConfigPath
	}

	cfg, err := config.LoadConfig(configPath)
	if err != nil {
		return fmt.Errorf("load config: %w", err)
	}

	if len(cfg.Sources) == 0 {
		term.Info("No sources configured.")
		return nil
	}

	term.Header(fmt.Sprintf("Sources in %s (%d)", configPath, len(cfg.Sources)))
	fmt.Fprintln(term.out)

	// Column headers.
	fmt.Fprintf(term.out, "  %-10s %-30s %-10s %s\n", "TYPE", "PATH / URL", "WATCH", "EXTRA")
	fmt.Fprintf(term.out, "  %s\n", strings.Repeat("-", 65))

	for _, s := range cfg.Sources {
		location := sourceLocation(s)
		watchStr := "no"
		if s.Watch {
			watchStr = "yes"
		}
		extra := sourceExtra(s)
		fmt.Fprintf(term.out, "  %-10s %-30s %-10s %s\n", s.Type, truncate(location, 30), watchStr, extra)
	}
	fmt.Fprintln(term.out)
	return nil
}

func (t *Term) Println(msg string) {
	fmt.Fprintln(t.out, msg)
}

func detectLanguage() string {
	manifests := map[string]string{
		"go.mod":       "go",
		"package.json": "typescript",
		"Cargo.toml":   "rust",
		"pom.xml":      "java",
		"build.gradle": "java",
	}
	for file, lang := range manifests {
		if _, err := os.Stat(file); err == nil {
			return lang
		}
	}
	return ""
}

func (t *Term) Success(msg string) {
	fmt.Fprintf(t.out, "%s%s %s%s\n", ansiGreen, "\u2713", msg, ansiReset)
}

func sanitizeName(s string) string {
	s = strings.ToLower(strings.TrimSpace(s))
	var b strings.Builder
	for _, r := range s {
		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '-' {
			b.WriteRune(r)
		} else {
			b.WriteRune('-')
		}
	}
	return strings.Trim(b.String(), "-")
}

