func (w *repoWizard) Prompts(term *Term) (*config.SourceEntry, error) {
	term.Header("Repository (all-in-one) source")

	var url string
	for url == "" {
		url = term.Prompt("Repository URL", "")
		if url == "" {
			term.Info("  A repository URL is required.")
		}
	}

	branch := term.Prompt("Branch (default: remote default)", "")
	language := term.Prompt("Primary language (go, java, python, typescript, or leave blank to auto-detect)", "")
	watch := term.Confirm("Watch for changes?", true)

	return &config.SourceEntry{
		Type:     "repo",
		URL:      url,
		Branch:   branch,
		Language: language,
		Watch:    watch,
	}, nil
}

func (t *Term) Select(label string, options []string) int {
	if len(options) == 0 {
		return 0
	}
	fmt.Fprintf(t.out, "%s%s%s\n", ansiBold, label, ansiReset)
	for i, opt := range options {
		fmt.Fprintf(t.out, "  %d. %s\n", i+1, opt)
	}
	for {
		fmt.Fprintf(t.out, "Choice [1-%d]: ", len(options))
		line, ok := t.readLine()
		if !ok {
			return 0
		}
		var n int
		if _, err := fmt.Sscanf(line, "%d", &n); err == nil {
			if n >= 1 && n <= len(options) {
				return n - 1
			}
		}
		fmt.Fprintf(t.out, "  Please enter a number between 1 and %d.\n", len(options))
	}
}

func (w *urlWizard) Prompts(term *Term) (*config.SourceEntry, error) {
	term.Header("URL source")
	term.Info("Enter HTTP/S URLs to ingest (e.g. https://example.com/api-docs).")

	var urls []string
	for len(urls) == 0 {
		urls = term.MultiLine("URLs")
		if len(urls) == 0 {
			term.Info("  At least one URL is required.")
		}
	}
	pollInterval := term.Prompt("Poll interval", "5m")

	return &config.SourceEntry{
		Type:         "url",
		URLs:         urls,
		PollInterval: pollInterval,
	}, nil
}

func (w *videoWizard) Prompts(term *Term) (*config.SourceEntry, error) {
	term.Header("Video source")
	term.Info("Enter paths to video files or directories (supported: mp4, mov, mkv, avi, webm).")

	paths := term.MultiLine("Paths")
	if len(paths) == 0 {
		paths = []string{"."}
	}

	// Keyframe extraction mode selection.
	term.Info("  Keyframe extraction mode:")
	term.Info("    1. interval — extract at fixed time intervals (default)")
	term.Info("    2. scene    — extract on scene changes")
	term.Info("    3. iframes  — extract all I-frames")
	modeChoice := term.Prompt("Mode", "1")

	mode := "interval"
	switch modeChoice {
	case "2":
		mode = "scene"
	case "3":
		mode = "iframes"
	}

	var interval string
	var threshold float64
	switch mode {
	case "interval":
		interval = term.Prompt("Keyframe interval", "30s")
	case "scene":
		// Default threshold set programmatically; not prompted to keep UX simple.
		threshold = 0.3
	}

	maxSize := term.Prompt("Max file size", "2GB")
	watch := term.Confirm("Watch for changes?", true)

	entry := &config.SourceEntry{
		Type:             "video",
		Paths:            paths,
		KeyframeMode:     mode,
		KeyframeInterval: interval,
		MaxFileSize:      maxSize,
		Watch:            watch,
	}
	if threshold > 0 {
		entry.SceneThreshold = threshold
	}

	return entry, nil
}

func (t *Term) Confirm(label string, defaultYes bool) bool {
	if defaultYes {
		fmt.Fprintf(t.out, "%s [Y/n]: ", label)
	} else {
		fmt.Fprintf(t.out, "%s [y/N]: ", label)
	}
	line, _ := t.readLine()
	if line == "" {
		return defaultYes
	}
	switch strings.ToLower(line) {
	case "y", "yes":
		return true
	case "n", "no":
		return false
	default:
		return defaultYes
	}
}

func (t *Term) Header(text string) {
	fmt.Fprintf(t.out, "\n%s%s%s\n", ansiBold, text, ansiReset)
}

