type SourceWizard interface {
	// Name is the human-readable display name shown in the source menu.
	Name() string

	// TypeKey is the config type identifier (e.g., "ast", "git").
	TypeKey() string

	// Description is a one-line summary shown next to the name.
	Description() string

	// Available reports whether this source type is ready to use.
	// Returns (true, "") when available, or (false, "reason") when not.
	Available() (bool, string)

	// Prompts runs the interactive wizard and returns a populated SourceEntry.
	Prompts(term *Term) (*config.SourceEntry, error)
}

func runSourceMenu(term *Term, info *ProjectInfo) ([]config.SourceEntry, error) {
	wizards := Wizards()
	selected := make([]bool, len(wizards))

	// Pre-select based on detection instead of selecting everything.
	for i, w := range wizards {
		ok, _ := w.Available()
		if !ok {
			continue
		}
		selected[i] = shouldPreselect(w.TypeKey(), info)
	}

	for {
		term.Header("Select sources to ingest (enter numbers to toggle, done to finish):")
		fmt.Fprintln(term.out)
		for i, w := range wizards {
			ok, reason := w.Available()
			mark := " "
			if selected[i] {
				mark = "x"
			}
			label := fmt.Sprintf("%s — %s", w.Name(), w.Description())
			if !ok {
				label = fmt.Sprintf("%s (%s)", label, reason)
			}
			fmt.Fprintf(term.out, "  [%s] %d. %s\n", mark, i+1, label)
		}
		fmt.Fprintln(term.out)
		fmt.Fprintf(term.out, "  Toggle> ")
		line, ok := term.readLine()
		if !ok {
			break
		}
		line = strings.TrimSpace(line)

		if strings.EqualFold(line, "done") || line == "" {
			break
		}

		var n int
		if _, err := fmt.Sscanf(line, "%d", &n); err != nil || n < 1 || n > len(wizards) {
			term.Info(fmt.Sprintf("  Enter a number 1-%d or 'done'.", len(wizards)))
			continue
		}
		idx := n - 1
		ok, reason := wizards[idx].Available()
		if !ok {
			term.Info(fmt.Sprintf("  %s is %s.", wizards[idx].Name(), reason))
			continue
		}
		selected[idx] = !selected[idx]
	}

	// Run prompts for each selected wizard, passing detection info for defaults.
	var sources []config.SourceEntry
	for i, w := range wizards {
		if !selected[i] {
			continue
		}
		entry, err := w.Prompts(term)
		if err != nil {
			return nil, fmt.Errorf("wizard %s: %w", w.Name(), err)
		}
		sources = append(sources, *entry)
	}
	return sources, nil
}

func addNonInteractive(typeKey string, args []string) (*config.SourceEntry, error) {
	switch typeKey {
	case "ast":
		return parseASTFlags(args)
	case "git":
		return parseGitFlags(args)
	case "repo":
		return parseRepoFlags(args)
	case "docs":
		return parseDocsFlags(args)
	case "config":
		return parseConfigFlags(args)
	case "url":
		return parseURLFlags(args)
	case "image":
		return parseImageFlags(args)
	case "video":
		return parseVideoFlags(args)
	case "audio":
		return parseAudioFlags(args)
	default:
		return nil, fmt.Errorf("unknown source type %q (valid: ast, git, repo, docs, config, url, image, video, audio)", typeKey)
	}
}

func deriveNamespace(info *ProjectInfo) string {
	if info.GitRemote != "" {
		if ns := orgFromRemote(info.GitRemote); ns != "" {
			return ns
		}
	}
	return sanitizeName(info.DirName)
}

