	RegisterSourceWizard(&astWizard{})
}

func buildDetectedSources(info *ProjectInfo) []config.SourceEntry {
	var sources []config.SourceEntry

	if info.HasGit {
		if gitURL := resolvableGitURL(info.GitRemote); gitURL != "" {
			sources = append(sources, config.SourceEntry{
				Type:   "git",
				URL:    gitURL,
				Branch: "main",
				Watch:  true,
			})
		}
	}

	if info.Language != "" {
		sources = append(sources, config.SourceEntry{
			Type:     "ast",
			Path:     ".",
			Language: info.Language,
			Watch:    true,
		})
	}

	if info.HasDocs && len(info.DocPaths) > 0 {
		sources = append(sources, config.SourceEntry{
			Type:  "docs",
			Paths: info.DocPaths,
			Watch: true,
		})
	}

	if len(info.ConfigFiles) > 0 {
		sources = append(sources, config.SourceEntry{
			Type:  "config",
			Paths: info.ConfigFiles,
			Watch: true,
		})
	}

	if info.HasImages && len(info.ImagePaths) > 0 {
		sources = append(sources, config.SourceEntry{
			Type:  "image",
			Paths: info.ImagePaths,
			Watch: true,
		})
	}

	return sources
}

func splitComma(s string) []string {
	var out []string
	for _, part := range strings.Split(s, ",") {
		part = strings.TrimSpace(part)
		if part != "" {
			out = append(out, part)
		}
	}
	return out
}

