func (w *gitWizard) Prompts(term *Term) (*config.SourceEntry, error) {
	term.Header("Git history source")

	// Default to a RESOLVABLE identity for the current repo: the origin
	// remote, else the absolute path — never "." (empty system segment; the
	// audit's zero-git-history default).
	defaultURL := ""
	if _, err := os.Stat(".git"); err == nil {
		defaultURL = resolvableGitURL(detectGitRemote("."))
	}

	var repoURL string
	for repoURL == "" {
		repoURL = term.Prompt("Repository path or URL", defaultURL)
		if repoURL == "" {
			term.Info("  A repository path or URL is required.")
		}
	}
	// Normalize relative paths (including ".") to absolute so the source
	// identity does not depend on the daemon's working directory.
	if !strings.Contains(repoURL, "://") && !strings.Contains(repoURL, "@") {
		if abs, err := filepath.Abs(repoURL); err == nil {
			repoURL = abs
		}
	}
	branch := term.Prompt("Branch to track", "main")
	watch := term.Confirm("Watch for new commits?", true)

	return &config.SourceEntry{
		Type:   "git",
		URL:    repoURL,
		Branch: branch,
		Watch:  watch,
	}, nil
}

func Init(term *Term, configPath string, overrides ...*ProjectInfo) error {
	if configPath == "" {
		configPath = defaultConfigPath
	}

	// Warn if config already exists.
	if _, err := os.Stat(configPath); err == nil {
		term.Println(fmt.Sprintf("  %s already exists.", configPath))
		if !term.Confirm("Overwrite it?", false) {
			term.Info("Aborted.")
			return nil
		}
	}

	// Auto-detect project context (or use override).
	var info *ProjectInfo
	if len(overrides) > 0 && overrides[0] != nil {
		info = overrides[0]
	} else {
		dir, _ := os.Getwd()
		info = DetectProject(dir)
	}

	term.Header("semsource setup wizard")
	printDetectionSummary(term, info)

	// Step 1: namespace (with smart default). Validated inline: the namespace
	// becomes the org segment of every entity ID, and an invalid value would
	// pass the old wizard, boot cleanly, and produce a permanently empty
	// graph (audit 2026-07-19, init-config-validation).
	var namespace string
	for {
		namespace = term.Prompt("Organization name (namespace)", info.Namespace)
		if namespace == "" {
			return fmt.Errorf("namespace is required")
		}
		if err := config.ValidateNamespace(namespace); err == nil {
			break
		}
		term.Info("  Namespace must start with a letter or digit and contain only letters, digits, '-' or '_' (no dots or spaces).")
	}

	// Step 2: source type multi-select (pre-selected based on detection).
	sources, err := runSourceMenu(term, info)
	if err != nil {
		return err
	}

	if len(sources) == 0 {
		return fmt.Errorf("at least one source is required")
	}

	cfg := buildConfig(namespace, sources)

	return writeAndSummarize(term, configPath, cfg)
}
